#include <iostream>
#include <algorithm>

struct Node {
    int data;
    Node* left;
    Node* right;
    Node(int val) : data(val), left(nullptr), right(nullptr) {}
};

// Returns the height of the node, and updates 'diameter'
int calculateHeightAndDiameter(Node* root, int& diameter) {
    if (root == nullptr) return -1;

    int lh = calculateHeightAndDiameter(root->left, diameter);
    int rh = calculateHeightAndDiameter(root->right, diameter);

    // Longest path through current node is (lh + 1) + (rh + 1)
    diameter = std::max(diameter, lh + rh + 2);

    return 1 + std::max(lh, rh);
}

int getDiameter(Node* root) {
    int diameter = 0;
    calculateHeightAndDiameter(root, diameter);
    return diameter;
}
